#!/usr/bin/env perl

use strict;
use warnings;
use Cwd qw(abs_path);
use File::Basename;

my @args = @ARGV;
my $rocm_path = $ENV{"ROCM_PATH"};
my $dcc_command = "$rocm_path/llvm/bin/dcc";

if (!-x $dcc_command) {
    print STDERR "Error: dcc executable not found at $dcc_command\nPlease source env.sh!\n";
    exit(1);
}

my $script_path = $0;
my $cuda_path = dirname(dirname($script_path));
push @args, ("-dcccuda12", "-cuda-path=$cuda_path");

# Debug
# print "Executing: $dcc_command @args\n";

my @processed_args;
my $in_quote = 0;
foreach my $arg (@args) {
    if ($in_quote) {
        push @processed_args, $arg;
        if ($arg =~ /"\s*$/) {
            $in_quote = 0;
        }
    } else {
        if ($arg =~ /^"\s*/) {
            push @processed_args, $arg;
            if ($arg =~ /.*[^"]$/) {
                $in_quote = 1;
            }
        } else {
            push @processed_args, "'$arg'";
        }
    }
    # Debug
    # print "args: $arg\n";
}

my $CMD = "$dcc_command " . join(' ', @processed_args);

# Debug
# print "CMD: $CMD\n";

system($CMD);
if ($? == -1) {
    print "failed to execute: $!\n";
    exit($?);
} elsif ($? & 127) {
    printf "child died with signal %d, %s coredump\n",
           ($? & 127),  ($? & 128) ? 'with' : 'without';
    exit($?);
} else {
    my $CMD_EXIT_CODE = $? >> 8;
    exit($CMD_EXIT_CODE);
}
